function IncidentList({ incidencias, usuario, onCerrarIncidencia }) {
  const handleCerrar = (id) => {
    if (onCerrarIncidencia) {
      onCerrarIncidencia(id);
    }
  };

  return (
    <div className="card shadow p-3">
      <h3 className="mb-3">Listado de incidencias</h3>

      <table className="table table-bordered table-striped table-hover">
        <thead className="table-dark">
          <tr>
            <th>ID Título</th>
            <th>Usuario</th>
            <th>Urgencia</th>
            <th>Ubicación</th>
            <th>Estado</th>
            <th>Fecha Registro</th>
            <th>Acciones</th>
          </tr>
        </thead>

        <tbody>
          {incidencias.map((incidencia) => (
            <tr key={incidencia.id}>
              <td>{incidencia.id} {incidencia.titulo}</td>
              <td>{incidencia.usuario?.email || "N/A"}</td>
              <td>{incidencia.urgencia}</td>
              <td>{incidencia.ubicacion}</td>
              <td>{incidencia.estado}</td>
              <td>{incidencia.fecha_registro}</td>
              <td>
                {onCerrarIncidencia && usuario?.rol === "admin" && incidencia.estado !== "Cerrada" ? (
                  <button
                    className="btn btn-warning btn-sm"
                    onClick={() => handleCerrar(incidencia.id)}
                  >
                    Cerrar
                  </button>
                ) : null}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default IncidentList;
